// Composition example: Car HAS-A Engine, rather than being forced into an inheritance hierarchy
class Engine {
    void start() { System.out.println("Engine starting"); }
}

class Car {
    private final Engine engine;    // composition: delegate to another object

    Car(Engine engine) {
        this.engine = engine;
    }

    void start() {
        engine.start();             // delegates behavior instead of inheriting it
        System.out.println("Car ready to drive");
    }
}

public class Main {
    public static void main(String[] args) {
        new Car(new Engine()).start();
    }
}
